import net.sf.saxon.s9api.*;
import org.owasp.esapi.ESAPI;
import org.springframework.web.bind.annotation.*;

@RestController
public class XQueryControllerSecure {

  @GetMapping("/users/find")
  public String findUser(@RequestParam String userId) throws SaxonApiException {
    // Simple XML data
    String xmlData = "<users><user id='1' name='admin'/><user id='2' name='guest'/></users>";

    Processor processor = new Processor(false);
    XQueryCompiler compiler = processor.newXQueryCompiler();

    String sanitizedId = ESAPI.encoder().encodeForXPath(userId);

    // Secure: use of framework sanitization
    String query = "let $doc := parse-xml('" + xmlData + "') return $doc//user[@id='" + sanitizedId + "']/@name";
    XQueryExecutable exec = compiler.compile(query); // ✓ OK
    XQueryEvaluator evaluator = exec.load();
    XdmValue result = evaluator.evaluate();

    return "User: " + (result.size() == 0 ? "Not found" : result.toString());
  }
}


