using Confluent.Kafka;
using Saxon.Api;
using System;
using System.Collections.Generic;
using System.IO;
using System.Xml;

internal class Program
{
  private static Dictionary<string, string> config;

  static XdmNode LoadSampleDocument(Processor proc)
  {
    var xml = "<users><user id='1' name='admin'/><user id='2' name='guest'/></users>";
    var db = proc.NewDocumentBuilder();
    db.BaseUri = new Uri("urn:doc");
    using var xr = XmlReader.Create(new StringReader(xml));
    return db.Build(xr);
  }

  // Secure: pass user input as an external variable (no concatenation)
  private void FindUser_secure()
  {
    using var consumer = new ConsumerBuilder<Ignore, string>(config).Build();
    consumer.Subscribe("user-lookup-topic");
    var result = consumer.Consume(TimeSpan.FromSeconds(10));

    if (result is null)
      return;

    string userInput = result.Message.Value;

    var proc = new Processor();
    var doc = LoadSampleDocument(proc);

    // Secure: pass user input as an external variable (no concatenation)
    string xquery = "declare variable $id external; for $u in /users/user where $u/@id = $id return string($u/@name)";
    var compiler = proc.NewXQueryCompiler();
    var exec = compiler.Compile(xquery); // ✓ OK
    var eval = exec.Load();
    eval.ContextItem = doc;
    eval.SetExternalVariable(new QName("id"), new XdmAtomicValue(userInput));
    var queryResult = eval.Evaluate();
    Console.WriteLine($"User: {queryResult}");
  }
}

